import (
	"math/rand"
	"testing"
)

func bruteSum(nums []int, l, r int) int {
	total := 0
	for i := l; i <= r; i++ {
		total += nums[i]
	}
	return total
}

func TestSegmentTreeMatchesBruteForce(t *testing.T) {
	rng := rand.New(rand.NewSource(7))
	nums := make([]int, 40)
	for i := range nums {
		nums[i] = rng.Intn(21) - 10
	}
	tree := NewSegmentTree(append([]int(nil), nums...))
	for op := 0; op < 500; op++ {
		l := rng.Intn(len(nums))
		r := l + rng.Intn(len(nums)-l)
		if op%2 == 0 {
			delta := rng.Intn(11) - 5
			tree.AddRange(l, r, delta)
			for i := l; i <= r; i++ {
				nums[i] += delta
			}
			continue
		}
		if got, want := tree.SumRange(l, r), bruteSum(nums, l, r); got != want {
			t.Fatalf("op %d: SumRange(%d, %d) = %d, want %d", op, l, r, got, want)
		}
	}
}

func TestSegmentTreeSingleElementAndFullRange(t *testing.T) {
	tree := NewSegmentTree([]int{1, 2, 3, 4, 5})
	if got := tree.SumRange(0, 4); got != 15 {
		t.Fatalf("SumRange(0, 4) = %d, want 15", got)
	}
	if got := tree.SumRange(2, 2); got != 3 {
		t.Fatalf("SumRange(2, 2) = %d, want 3", got)
	}
	tree.AddRange(2, 2, 10)
	if got := tree.SumRange(2, 2); got != 13 {
		t.Fatalf("after AddRange(2, 2, 10): SumRange(2, 2) = %d, want 13", got)
	}
	if got := tree.SumRange(0, 4); got != 25 {
		t.Fatalf("after AddRange(2, 2, 10): SumRange(0, 4) = %d, want 25", got)
	}
	tree.AddRange(0, 4, -1)
	if got := tree.SumRange(0, 4); got != 20 {
		t.Fatalf("after AddRange(0, 4, -1): SumRange(0, 4) = %d, want 20", got)
	}
}

