func TestSegmentTreeHandlesLargeMixedWorkload(t *testing.T) {
	const n = 500000
	const ops = 400000
	rng := rand.New(rand.NewSource(11))
	nums := make([]int, n)
	for i := range nums {
		nums[i] = i % 7
	}
	tree := NewSegmentTree(append([]int(nil), nums...))

	// A running total kept in parallel, so the whole-array query below is
	// checked against arithmetic instead of against a second scan.
	total := 0
	for _, v := range nums {
		total += v
	}
	for op := 0; op < ops; op++ {
		l := rng.Intn(n)
		r := l + rng.Intn(n-l)
		if op%2 == 0 {
			delta := rng.Intn(9) - 4
			tree.AddRange(l, r, delta)
			total += delta * (r - l + 1)
			continue
		}
		left := tree.SumRange(0, l)
		right := tree.SumRange(l, n-1)
		mid := tree.SumRange(l, l)
		if got := left + right - mid; got != tree.SumRange(0, n-1) {
			t.Fatalf("op %d: split at %d disagrees with the whole-array sum", op, l)
		}
	}
	if got := tree.SumRange(0, n-1); got != total {
		t.Fatalf("SumRange(0, %d) = %d, want %d", n-1, got, total)
	}
}

