type SegmentTree struct {
	n    int
	sum  []int
	lazy []int
}

func NewSegmentTree(nums []int) *SegmentTree {
	t := &SegmentTree{n: len(nums), sum: make([]int, 4*len(nums)+4), lazy: make([]int, 4*len(nums)+4)}
	if t.n > 0 {
		t.build(1, 0, t.n-1, nums)
	}
	return t
}

func (t *SegmentTree) build(node, lo, hi int, nums []int) {
	if lo == hi {
		t.sum[node] = nums[lo]
		return
	}
	mid := (lo + hi) / 2
	t.build(2*node, lo, mid, nums)
	t.build(2*node+1, mid+1, hi, nums)
	t.sum[node] = t.sum[2*node] + t.sum[2*node+1]
}

func (t *SegmentTree) apply(node, lo, hi, delta int) {
	t.sum[node] += delta * (hi - lo + 1)
	t.lazy[node] += delta
}

func (t *SegmentTree) push(node, lo, mid, hi int) {
	if t.lazy[node] == 0 {
		return
	}
	t.apply(2*node, lo, mid, t.lazy[node])
	t.apply(2*node+1, mid+1, hi, t.lazy[node])
	t.lazy[node] = 0
}

func (t *SegmentTree) AddRange(l, r, delta int) {
	if t.n == 0 || l > r {
		return
	}
	t.add(1, 0, t.n-1, l, r, delta)
}

func (t *SegmentTree) add(node, lo, hi, l, r, delta int) {
	if r < lo || hi < l {
		return
	}
	if l <= lo && hi <= r {
		t.apply(node, lo, hi, delta)
		return
	}
	mid := (lo + hi) / 2
	t.push(node, lo, mid, hi)
	t.add(2*node, lo, mid, l, r, delta)
	t.add(2*node+1, mid+1, hi, l, r, delta)
	t.sum[node] = t.sum[2*node] + t.sum[2*node+1]
}

func (t *SegmentTree) SumRange(l, r int) int {
	if t.n == 0 || l > r {
		return 0
	}
	return t.query(1, 0, t.n-1, l, r)
}

func (t *SegmentTree) query(node, lo, hi, l, r int) int {
	if r < lo || hi < l {
		return 0
	}
	if l <= lo && hi <= r {
		return t.sum[node]
	}
	mid := (lo + hi) / 2
	t.push(node, lo, mid, hi)
	return t.query(2*node, lo, mid, l, r) + t.query(2*node+1, mid+1, hi, l, r)
}

