import (
	"math/rand"
	"testing"
)

// bruteAssign tries every permutation, which is only usable for tiny inputs.
func bruteAssign(cost [][]int) int {
	n := len(cost)
	perm := make([]int, n)
	for i := range perm {
		perm[i] = i
	}
	best := -1
	var walk func(int)
	walk = func(k int) {
		if k == n {
			total := 0
			for i, j := range perm {
				total += cost[i][j]
			}
			if best < 0 || total < best {
				best = total
			}
			return
		}
		for i := k; i < n; i++ {
			perm[k], perm[i] = perm[i], perm[k]
			walk(k + 1)
			perm[k], perm[i] = perm[i], perm[k]
		}
	}
	walk(0)
	if best < 0 {
		return 0
	}
	return best
}

func TestMinAssignmentCostSmallCases(t *testing.T) {
	if got := minAssignmentCost([][]int{{5}}); got != 5 {
		t.Fatalf("one worker: got %d, want 5", got)
	}
	// The cheapest cell for worker 0 is task 0, but taking it forces worker 1
	// onto a 90, so the greedy pick is not the cheapest assignment.
	grid := [][]int{
		{1, 10},
		{2, 90},
	}
	if got := minAssignmentCost(grid); got != 12 {
		t.Fatalf("greedy trap: got %d, want 12", got)
	}
}

func TestMinAssignmentCostMatchesBruteForce(t *testing.T) {
	rng := rand.New(rand.NewSource(3))
	for n := 1; n <= 7; n++ {
		for trial := 0; trial < 12; trial++ {
			grid := make([][]int, n)
			for i := range grid {
				grid[i] = make([]int, n)
				for j := range grid[i] {
					grid[i][j] = rng.Intn(50)
				}
			}
			if got, want := minAssignmentCost(grid), bruteAssign(grid); got != want {
				t.Fatalf("n=%d trial=%d: got %d, want %d for %v", n, trial, got, want, grid)
			}
		}
	}
}

func TestMinAssignmentCostEighteenWorkers(t *testing.T) {
	const n = 18
	rng := rand.New(rand.NewSource(19))
	// One planted permutation holds every cheap cell. Every other assignment
	// misses at least two of them, so it pays at least 200 extra.
	planted := rng.Perm(n)
	grid := make([][]int, n)
	want := 0
	for i := range grid {
		grid[i] = make([]int, n)
		for j := range grid[i] {
			grid[i][j] = 100 + rng.Intn(900)
		}
		grid[i][planted[i]] = 1 + rng.Intn(10)
		want += grid[i][planted[i]]
	}
	if got := minAssignmentCost(grid); got != want {
		t.Fatalf("18 workers: got %d, want %d", got, want)
	}
}

